import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';
import { rpgDefinition, buySword } from '../dist/rpg-example.js';

const sandbox = { crypto, TextEncoder, structuredClone, setTimeout, clearTimeout, console: { info() {}, error() {}, warn() {}, log() {} } };
const extensionCode = (await readFile('dist/index.js', 'utf8')).replaceAll('import.meta.url', JSON.stringify('http://localhost/solve/index.js'));
vm.runInNewContext(extensionCode, sandbox, { filename: 'solve-bundle.js' });
const api = sandbox.SOLVE;
const { version } = JSON.parse(await readFile('package.json', 'utf8'));
assert.equal(api.version, version);
assert.equal(api.VERSION, version);
const manifest = JSON.parse(await readFile('dist/manifest.json', 'utf8'));
assert.equal(manifest.version, version);
assert.equal(typeof api.openDebugger, 'function');
assert.ok((await readFile('dist/debug.html', 'utf8')).includes('debug.js'));
assert.ok((await readFile('dist/debug.css', 'utf8')).includes('--green'));
assert.ok((await readFile('dist/debug.js', 'utf8')).length > 10000);
const inlineHtml = await readFile('dist/debug-inline.html', 'utf8');
assert.equal((inlineHtml.match(/<\/script>/gu) ?? []).length, 1, '内联面板不能被JS字符串中的标签提前截断');
const inlineScript = inlineHtml.match(/<script>([\s\S]*)<\/script>/u)?.[1];
assert.ok(inlineScript);
new vm.Script(inlineScript);
const embeddedCode = await readFile('dist/embedded.js', 'utf8');
assert.equal(/<\/script/iu.test(embeddedCode), false, '助手内联脚本不能含HTML结束标签');
const parent = vm.createContext({ crypto, TextEncoder, structuredClone, setTimeout, clearTimeout, console: sandbox.console, document: { body: null, createElement: () => ({ remove() {} }), head: { append(script) { vm.runInContext(script.textContent, parent); } } } });
parent.SillyTavern = { getContext: () => ({}) };
const iframe = vm.createContext({ window: { parent, addEventListener() {} } });
vm.runInContext(embeddedCode, iframe);
assert.equal(parent.SOLVE.version, version);
assert.equal(vm.runInContext('SOLVE.version', iframe), version);
assert.equal(parent.SOLVE.distribution().native, false);
assert.equal(parent.SOLVE.distribution().providers[0].kind, 'embedded');
const host = await import('../dist/sillytavern.js');
assert.equal(typeof host.SolveSessionManager, 'function');
assert.equal(typeof host.attachSillyTavern, 'function');
const definition = await api.compile(rpgDefinition);
const core = new api.SolveCore(definition);
const result = await core.execute(buySword, await core.initialize());
assert.equal(result.feedback.length, 0);
assert.equal(result.state.data.characters.player.gold, 70);
assert.equal(result.state.data.characters.player.inventory.sword.name, '铁剑');
assert.ok(api.toJson(definition, result.state).includes('"@player"'));
assert.ok(api.toToon(definition, result.state).includes('@player'));
console.log('构建包验证通过：三载体、父页面执行、内嵌面板语法和跨上下文定义可运行。');
